import json,os,subprocess,time
r={"pid":os.getpid(),"begin":time.monotonic_ns(),"clock":str(time.get_clock_info("monotonic"))}
for p in ["/proc/uptime","/proc/self/timens_offsets"]:
 try:r[p]=open(p).read()
 except OSError as e:r[p]=str(e)
for i in range(2):
 r["child"+str(i)]=json.loads(subprocess.check_output(["/usr/bin/python3","-c","import os,time,json; print(json.dumps(dict(pid=os.getpid(),monotonic_ns=time.monotonic_ns())))"]))
 time.sleep(.2)
r["end"]=time.monotonic_ns();print(json.dumps(r))
